SELECT r.request_id,r.created_at,r.status,r.requested_by,r.facility,r.payment,f.name AS facility_name,p.payment_id,p.payment_status,p.created_at AS payment_created_at,(SELECT jsonb_agg(jsonb_build_object('booking_id',b.name,'booking_status',b.booking_status,'created_at',b.created_at)) FROM public."SSP_Facility_Booking" b WHERE b.payment=r.payment) AS confirmed_bookings FROM public."SSP_Facility_Booking_Request" r LEFT JOIN public."SSP_Payment" p ON p.pay_rec_id=r.payment LEFT JOIN public."SSP_Facility" f ON f.id=r.facility ORDER BY r.created_at DESC NULLS LAST LIMIT 8;
